/**
 * Storno objednavky (POST id, reason).
 *
 * Jde pres domenu: ta vrati castku k vraceni zakaznikovi a uvolni
 * rezervace ve skladu. Penize posila obchod rucne, proto poznamka a audit.
 */
public function cancelAction()
{
    global $db;
    legacy_db();
    auth_require('obchod');

    $id = post_param('id');
    if (!is_post()) {
        return $this->redirect(admin_url('order', array('id' => get_param('id'))));
    }

    $order = $db->one("SELECT * FROM orders WHERE id = " . $db->quote($id));
    if ($order === null) {
        return $this->notFound('Objednávka ' . $id . ' neexistuje');
    }
    $detailUrl = admin_url('order', array('id' => $id));

    if ($order['status'] == 'cancelled') {
        flash('Objednávka už je stornovaná', 'error');

        return $this->redirect($detailUrl);
    }

    $reason = trim((string) post_param('reason'));
    if ($reason === '') {
        flash('Vyplňte důvod storna', 'error');

        return $this->redirect($detailUrl);
    }

    try {
        $refund = legacy_ordering()->cancel($id, $reason);
    } catch (InvalidOrderStateTransitionException $e) {
        flash('Objednávku ve stavu ' . order_state_label($order['status']) . ' nelze stornovat', 'error');

        return $this->redirect($detailUrl);
    }

    $refundText = format_price($refund->amountInCents, $refund->currency->value);
    audit_log('order', $id, 'storno', array(
        'from'            => $order['status'],
        'reason'          => $reason,
        'refund_in_cents' => $refund->amountInCents,
        'refund_currency' => $refund->currency->value,
    ));

    $note = 'Storno: ' . $reason;
    if ($refund->amountInCents > 0) {
        $note .= "\nVrátit zákazníkovi: " . $refundText;
    }
    $db->exec("INSERT INTO order_notes (order_id, author, note, created_at) VALUES ("
        . $db->quote($id) . ", " . $db->quote(auth_login_name()) . ", " . $db->quote($note) . ", '" . date('Y-m-d H:i:s') . "')");

    $c = $db->one("SELECT email FROM customers WHERE id = " . $db->quote($order['customer_id']));
    if ($c) {
        $body = "Dobrý den,\n\nvaše objednávka " . $id . " byla stornována.\n";
        if ($refund->amountInCents > 0) {
            $body .= "Zaplacenou částku " . $refundText . " vám vrátíme.\n";
        }
        send_mail($c['email'], 'Vaše objednávka byla stornována', $body);
    }

    cache_delete('dashboard_stats');

    if ($refund->amountInCents > 0) {
        flash('Objednávka stornována, zboží vráceno na sklad. Vraťte zákazníkovi ' . $refundText . '.');
    } else {
        flash('Objednávka stornována, zboží vráceno na sklad. Nebyla zaplacená, nic se nevrací.');
    }

    return $this->redirect($detailUrl);
}

